package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.network.syncher.*;import net.minecraft.server.level.*;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import java.util.*;
/** Server-owned inventory and single-bay transaction; stored payloads are never world entities. */
public class Ndc01Entity extends Wd01Entity implements PatriotLauncher {
 private static final EntityDataAccessor<Integer> BAY=SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.INT),PHASE=SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.INT),FAILURE=SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<Long> START=SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.LONG);
 private static final EntityDataAccessor<Boolean> FLOAT=SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.BOOLEAN);
 private static final List<EntityDataAccessor<ItemStack>> CARGO=new ArrayList<>();static{for(int i=0;i<18;i++)CARGO.add(SynchedEntityData.defineId(Ndc01Entity.class,EntityDataSerializers.ITEM_STACK));}
 public final SimpleContainer bays=new SimpleContainer(18){@Override public int getMaxStackSize(){return 1;}@Override public boolean canPlaceItem(int slot,ItemStack s){return !busy()&&!PlatformInventory.editing(Ndc01Entity.this)&&allowed(s);}@Override public void setChanged(){super.setChanged();if(loadIds!=null)syncCargo();}};
 private UUID[]loadIds=new UUID[18];private UUID navalOwner,pendingActor,pendingLoad,pendingTarget,pendingEntity;private String ownerName="";private boolean settled,suppressDrops;private long nextLaunch;private Wd01Water.Support support=new Wd01Water.Support(0,0,0,0);public UUID selectedTarget;
 public Ndc01Entity(EntityType<? extends Ndc01Entity>type,Level level){super(type,level);}
 @Override protected void defineSynchedData(){super.defineSynchedData();entityData.define(BAY,-1);entityData.define(PHASE,0);entityData.define(FAILURE,0);entityData.define(START,0L);entityData.define(FLOAT,false);for(var d:CARGO)entityData.define(d,ItemStack.EMPTY);}
 public static boolean allowed(ItemStack s){return !s.isEmpty()&&s.is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM,net.minecraft.resources.ResourceLocation.tryParse("sbwdroneconfig:ndc01_payloads")))&&(s.getItem()==AddonItems.ID01.get()||s.getItem() instanceof CubedFpvDroneItem);}
 public ItemStack cargo(int i){return level().isClientSide?entityData.get(CARGO.get(i)):bays.getItem(i);}public UUID loadId(int i){return i>=0&&i<18?loadIds[i]:null;}
 private void syncCargo(){if(level().isClientSide||bays==null)return;for(int i=0;i<18;i++){var old=entityData.get(CARGO.get(i));var current=bays.getItem(i);if(!ItemStack.matches(old,current)){loadIds[i]=current.isEmpty()?null:UUID.randomUUID();entityData.set(CARGO.get(i),current.copy());}}}
 public int bay(){return entityData.get(BAY);}public int phase(){return entityData.get(PHASE);}public int reason(){return entityData.get(FAILURE);}public boolean busy(){return phase()!=0;}public boolean closing(){return phase()==4;}public boolean floating(){return entityData.get(FLOAT);}
 public double hatchTime(int slot,float partial){if(slot!=bay()||!busy())return 0;if(phase()==2||phase()==3)return 1.2;return Mth.clamp((level().getGameTime()-entityData.get(START)+partial)/20d,0,1.2);}
 public int state(int i){return bay()==i&&busy()?phase():cargo(i).isEmpty()?0:reason()!=0&&bay()==i?6:5;}
 private void phase(int value){entityData.set(PHASE,value);entityData.set(START,level().getGameTime());}
 private boolean fail(ServerPlayer p,int reason){entityData.set(FAILURE,reason);if(p!=null)p.displayClientMessage(Component.translatable("ndc01.reason."+reason),true);return false;}
 @Override public void claimOwner(ServerPlayer p){if(permitted(p)&&navalOwner==null){navalOwner=p.getUUID();ownerName=p.getScoreboardName();}super.claimOwner(p);}
 @Override public boolean permitted(ServerPlayer p){return p!=null&&(navalOwner==null||navalOwner.equals(p.getUUID())||p.hasPermissions(2))&&super.permitted(p);}
 public boolean canUse(ServerPlayer p){return p!=null&&!settled&&isAlive()&&!isRemoved()&&!isWreck()&&p.isAlive()&&!p.isSpectator()&&!InjuryServer.cannotOperate(p)&&p.level()==level()&&permitted(p)&&(p.distanceToSqr(this)<=100||VatagSessions.controlling(p,this)||CarrierFleet.access(p,this));}
 public void openBays(ServerPlayer p){if(!canUse(p))return;input(p,64,0,0);net.minecraftforge.network.NetworkHooks.openScreen(p,new SimpleMenuProvider((id,inv,who)->new Ndc01Menu(id,inv,this),Component.literal("MAGURA MV11 / NDC-01")),buf->buf.writeInt(getId()));}
 public void action(ServerPlayer p,int action){if(action==25){CarrierFleet.open(p,0);return;}if(action==24){if(canUse(p)&&bay()>=0)PlatformInventory.open(this,bay(),p);return;}if(PlatformInventory.guard(this,p))return;if(!canUse(p)||busy())return;if(action>=0&&action<18){entityData.set(BAY,action);entityData.set(FAILURE,0);return;}int slot=bay();if(slot<0||slot>=18)return;if(action==20){if(cargo(slot).isEmpty()){fail(p,1);return;}Ndc01Monitor.bind(p,this,slot);p.closeContainer();return;}if(action==21){selectedTarget=nextTarget(p,slot);return;}if(action==22){var home=CarrierFleet.home(p.getMainHandItem());if(home!=null&&!home.equals(getUUID())){CarrierFleet.message(p,"Monitor belongs to another carrier. Link this carrier explicitly first.");return;}Ndc01Monitor.selectBay(p,this,slot,false);if(!Ndc01Monitor.ready(p,this,slot)){CarrierFleet.message(p,"Select a loaded bay and hold its carrier monitor.");return;}request(p,slot,loadId(slot),selectedTarget,false);return;}if(action==23){CarrierFleet.request(p,getUUID());}}
 public Entity inventoryDrone(int slot,ServerPlayer p){
    if(!canUse(p)||slot<0||slot>=18||!allowed(cargo(slot)))return null;claimOwner(p);
    if(cargo(slot).is(AddonItems.ID01.get()))return interceptor(slot,p);
    var d=PlatformInventory.hydrate(AddonEntities.CUBED_FPV_DRONE.get().create(level()),PlatformInventory.saved(cargo(slot)));
    if(d!=null){SbwCompat.ensureDroneOwner(d,p);d.setPos(anchor(slot));}return d;
 }
 public void inventoryChanged(int slot){if(slot>=0&&slot<18)entityData.set(CARGO.get(slot),bays.getItem(slot).copy());}
 private Id01Entity interceptor(int slot,ServerPlayer p){var s=cargo(slot);if(s.getItem()!=AddonItems.ID01.get())return null;var d=AddonEntities.ID01.get().create(level());if(d==null)return null;var tag=PlatformMonitor.tag(s);if(tag.contains("Id01Saved",10)){var saved=tag.getCompound("Id01Saved").copy();for(String k:new String[]{"UUID","Pos","Motion","Rotation"})saved.remove(k);saved.putInt("Id01Mode",0);d.load(saved);}d.setPos(anchor(slot));d.setYRot(getYRot());d.yRotO=d.getYRot();if(d.ownerId()==null){if(navalOwner==null)return null;d.carrierOwner(navalOwner,ownerName);}return d;}
 private CubedFpvDroneEntity prepareFpv(int slot,ServerPlayer p){var fpv=AddonEntities.CUBED_FPV_DRONE.get().create(level());if(fpv==null||p==null)return null;var stack=cargo(slot);var tag=PlatformMonitor.tag(stack);var saved=tag.contains("EntityTag",10)?tag.getCompound("EntityTag").copy():new CompoundTag(); if(!saved.isEmpty()){for(String k:new String[]{"UUID","Pos","Motion","Rotation","Passengers"})saved.remove(k);fpv.load(saved);}if(!Dc01Docking.owned(p,fpv)||fpv.isWreck()||fpv.getHealth()<=0||AddonConfig.enableBatterySystem()&&DroneBatterySystem.currentEnergy(fpv)<=0)return null;SbwCompat.ensureDroneOwner(fpv,p);Dc01Docking.neutralize(fpv);fpv.setPos(anchor(slot));fpv.setYRot(getYRot());fpv.yRotO=fpv.getYRot();fpv.setOnGround(false);return fpv;}
 public Vec3 anchor(int slot){return Ndc01Geometry.point(Ndc01Geometry.frame(this,1),Ndc01Geometry.MODEL.payload[slot]);}
 public UUID radar(){return level()instanceof ServerLevel l&&DefenseData.get(l).site(getUUID())!=null?DefenseData.get(l).site(getUUID()).radar:null;}
 private UUID nextTarget(ServerPlayer p,int slot){var d=interceptor(slot,p);if(d==null){fail(p,7);return null;}var data=DefenseData.get(p.serverLevel());var r=data.radar(p.serverLevel(),radar());if(r==null||!data.navalAllows(p.serverLevel(),radar(),getUUID(),p)){fail(p,8);return null;}var ids=new ArrayList<UUID>();for(var v:r.contacts){var n=(CompoundTag)v;if(n.hasUUID("UUID")&&Id01Radar.hostile(d,p.serverLevel().getEntity(n.getUUID("UUID"))))ids.add(n.getUUID("UUID"));}if(ids.isEmpty()){fail(p,9);return null;}return ids.get((ids.indexOf(selectedTarget)+1)%ids.size());}
 private boolean validTarget(Id01Entity d,ServerPlayer p,UUID goal,boolean automatic){if(!(level()instanceof ServerLevel l)||goal==null)return false;var data=DefenseData.get(l);var radar=data.radar(l,radar());return data.navalAllows(l,radar(),getUUID(),automatic?null:p)&&radar!=null&&l.getGameTime()-radar.scanned<=DefenseConfig.SCAN.get()*3L&&radar.contacts.stream().anyMatch(v->((CompoundTag)v).hasUUID("UUID")&&goal.equals(((CompoundTag)v).getUUID("UUID")))&&Id01Radar.hostile(d,l.getEntity(goal))&&d.distanceToSqr(l.getEntity(goal))<=Id01Config.RANGE.get()*Id01Config.RANGE.get();}
 private boolean corridor(int slot){var a=anchor(slot);var area=new AABB(a.add(-.35,-.02,-.35),a.add(.35,cargo(slot).getItem()==AddonItems.ID01.get()?2.6:2.0,.35));if(!level().hasChunksAt(BlockPos.containing(area.minX,area.minY,area.minZ),BlockPos.containing(area.maxX,area.maxY,area.maxZ))||!level().getWorldBorder().isWithinBounds(area))return false;for(var s:level().getBlockCollisions(this,area))if(!s.isEmpty())return false;return level().getEntities(this,area,e->e.isPickable()&&!e.isSpectator()&&e.isAlive()).isEmpty();}
 public boolean request(ServerPlayer p,int slot,UUID expected,UUID target,boolean automatic){if(PlatformInventory.guard(this,p))return false;if(!(level()instanceof ServerLevel)||settled||!isAlive()||isWreck()||busy()||level().getGameTime()<nextLaunch)return false;if(slot<0||slot>=18||expected==null||!expected.equals(loadId(slot))||!allowed(cargo(slot)))return fail(p,1);if(!automatic&&(p==null||!p.isAlive()||p.hasDisconnected()||p.isSpectator()||InjuryServer.cannotOperate(p)||!permitted(p)||p.level()!=level()||p.distanceToSqr(this)>Math.pow(AddonConfig.droneMaxRange(),2)))return fail(p,2);if(getEnergy()<Ndc01Config.LAUNCH.get()||!floating()||DroneJamStateManager.isHardJammed(this))return fail(p,3);var id=interceptor(slot,p);if(id!=null&&(!Objects.equals(id.ownerId(),navalOwner)||p!=null&&!id.permitted(p)||!validTarget(id,p,target,automatic)||id.energy()<=Math.min(Id01Config.RESERVE.get(),AddonConfig.maxEnergy()*.8)))return fail(p,9);if(id==null&&prepareFpv(slot,p)==null)return fail(p,3);if(!corridor(slot))return fail(p,4);if(id==null&&(p==null||!Ndc01Monitor.ready(p,this,slot)||!SbwCompat.hasEquippedFpvGoggles(p)))return fail(p,5);
  entityData.set(BAY,slot);entityData.set(FAILURE,0);pendingActor=p==null?null:p.getUUID();pendingLoad=expected;pendingTarget=target;phase(1);nextLaunch=level().getGameTime()+60;DefenseData.get((ServerLevel)level()).reserve(getUUID(),target==null?getUUID():target,level().getGameTime());return true;}
 private void commit(){int slot=bay();var l=(ServerLevel)level();var p=pendingActor==null?null:l.getServer().getPlayerList().getPlayer(pendingActor);if(slot<0||pendingLoad==null||!pendingLoad.equals(loadId(slot))||!allowed(cargo(slot))||!corridor(slot)||getEnergy()<Ndc01Config.LAUNCH.get()||!floating()||(pendingActor!=null&&(p==null||p.hasDisconnected()||!p.isAlive()||p.isSpectator()||p.level()!=level()||InjuryServer.cannotOperate(p)||!permitted(p)))){fail(p,4);phase(4);return;}var d=interceptor(slot,p);Entity launched;
  if(d!=null){if(!Objects.equals(d.ownerId(),navalOwner)||p!=null&&!d.permitted(p)||!validTarget(d,p,pendingTarget,pendingActor==null)||!d.carrierLaunch(pendingTarget)){fail(p,9);phase(4);return;}launched=d;}
  else {if(!Ndc01Monitor.ready(p,this,slot)||!SbwCompat.hasEquippedFpvGoggles(p)){fail(p,5);phase(4);return;}var fpv=prepareFpv(slot,p);if(fpv==null){fail(p,3);phase(4);return;}launched=fpv;}
  launched.setDeltaMovement(getDeltaMovement().add(0,.25,0));Ndc01Monitor.departure(launched,this);if(!l.addFreshEntity(launched)){fail(p,4);phase(4);return;}
  // Commit inventory before any callbacks. The transaction can never consume a replacement load.
  CarrierFleetData.get(l).register(this,getUUID(),true);CarrierFleetData.get(l).register(launched,getUUID(),false);bays.setItem(slot,ItemStack.EMPTY);consumeEnergy(Ndc01Config.LAUNCH.get());phase(3);pendingEntity=launched.getUUID();
 }
 @Override public void baseTick(){super.baseTick();if(level().isClientSide)return;if(busy())ChunkTicketManager.touchDrone(this,1);if(tickCount%20==1&&navalOwner!=null){var data=DefenseData.get((ServerLevel)level());data.register(new DefenseData.Site(getUUID(),4,blockPosition(),Direction.SOUTH,navalOwner,ownerName));}if(phase()==3&&pendingEntity!=null&&level().getGameTime()-entityData.get(START)>=3)completeHandoff();if(phase()==1&&level().getGameTime()-entityData.get(START)>=24){phase(2);return;}if(phase()==2){commit();return;}if(phase()==3&&level().getGameTime()-entityData.get(START)>=40&&bayClear())phase(4);else if(phase()==4&&level().getGameTime()-entityData.get(START)>=24){phase(0);if(operator()==null)ChunkTicketManager.releaseDrone(this);pendingActor=pendingLoad=pendingTarget=pendingEntity=null;}}
 private void completeHandoff(){var l=(ServerLevel)level();var e=l.getEntity(pendingEntity);var p=pendingActor==null?null:l.getServer().getPlayerList().getPlayer(pendingActor);if(e==null||e.isRemoved()||!Ndc01Monitor.pendingMatches(p,this,pendingLoad)){pendingEntity=pendingLoad=null;return;}if(e.getPersistentData().getBoolean(DroneWaterDisconnectSystem.TAG_WATER_DISCONNECTED)||e.isInWaterOrBubble())return;Ndc01Monitor.launched(p,this,e);pendingEntity=pendingLoad=null;}
 private boolean bayClear(){var at=anchor(bay());var space=new AABB(at.add(-.55,-.1,-.55),at.add(.55,1.4,.55));return level().getEntities(this,space,e->e instanceof com.atsuishio.superbwarfare.entity.vehicle.DroneEntity&&e.isAlive()&&!e.isRemoved()).isEmpty();}
 @Override public void beforeShip(){int count=0;double sum=0;var surface=position().add(0,.7,0);for(double x:new double[]{-1.25,0,1.25})for(double z:new double[]{-4.8,0,4.8}){var s=Wd01Water.surface(level(),Wd01Water.point(surface,getYRot(),x,z));if(s!=null&&s.depth()>=.8){count++;sum+=s.height();}}support=new Wd01Water.Support(count,count==0?surface.y:sum/count,0,0);if(!level().isClientSide)entityData.set(FLOAT,count>=5);setSprintInputDown(false);if(!remotelyControlled()||upInputDown()||getEnergy()<=0||!floating()||isWreck()){setForwardInputDown(false);setBackInputDown(false);setLeftInputDown(false);setRightInputDown(false);setPower(Mth.approach(getPower(),0,.05f));setDeltaMovement(getDeltaMovement().multiply(.88,1,.88));setDeltaRot(getDeltaRot()*.65f);}}
 @Override public void afterShip(){if(floating()){var v=getDeltaMovement();double lift=Mth.clamp((support.height()-.7-getY())*.075-v.y*.48,-.12,.12);setDeltaMovement(v.add(0,lift+computed().getGravity(),0));setXRot(Mth.approachDegrees(getXRot(),0,.4f));setZRot(Mth.approachDegrees(getRoll(),0,.4f));}else{setPower(0);setDeltaMovement(getDeltaMovement().multiply(.45,1,.45));}if(!level().isClientSide&&remotelyControlled()&&tickCount%10==0)consumeEnergy((int)Math.ceil(Ndc01Config.IDLE.get()/2d+Math.abs(getPower())*Ndc01Config.USE.get()/2d));}
 @Override public org.joml.Matrix4d cameraFrame(boolean mast,float partial){var at=mast?Ndc01Geometry.MODEL.mast:Ndc01Geometry.MODEL.bow;return new org.joml.Matrix4d(getVehicleTransform(partial)).translate(-at.x,at.y,-at.z).rotateY(Math.toRadians(Mth.rotLerp(partial,getTurretYRotO(),getTurretYRot()))).rotateX(Math.toRadians(-Mth.lerp(partial,getTurretXRotO(),getTurretXRot())));}
 @Override public Vec3 camera(boolean mast,float partial){var v=cameraFrame(mast,partial).transformPosition(new org.joml.Vector3d());return new Vec3(v.x,v.y,v.z);}
 @Override protected AABB makeBoundingBox(){double a=Math.toRadians(getYRot()),x=Math.abs(Math.cos(a))*1.7+Math.abs(Math.sin(a))*6.12,z=Math.abs(Math.sin(a))*1.7+Math.abs(Math.cos(a))*6.12;return new AABB(getX()-x,getY(),getZ()-z,getX()+x,getY()+4.46,getZ()+z);}
 @Override public boolean canCollideWith(Entity other){return !Dc01Docking.sameCarrier(this,other)&&super.canCollideWith(other);}
 @Override public AABB getBoundingBoxForCulling(){return getBoundingBox().inflate(.3);}
 @Override public InteractionResult interact(Player p,InteractionHand hand){var held=p.getItemInHand(hand);if(p instanceof ServerPlayer sp){if(!permitted(sp)||isRemoved())return InteractionResult.FAIL;claimOwner(sp);SbwCompat.ensureDroneOwner(this,sp);if(held.getItem()instanceof DefenseLinkTool){var data=DefenseData.get(sp.serverLevel());data.register(new DefenseData.Site(getUUID(),4,blockPosition(),Direction.SOUTH,navalOwner,ownerName));if(p.isShiftKeyDown()){data.unlink(getUUID());DefenseLinkTool.reply(sp,"UNLINKED");}else DefenseLinkTool.link(sp,held,getUUID());return InteractionResult.CONSUME;}if(p.isShiftKeyDown()&&held.is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR))return pack(sp)?InteractionResult.CONSUME:InteractionResult.FAIL;if(held.isEmpty()||allowed(held)||p.isShiftKeyDown()&&SbwCompat.isMonitor(held)){openBays(sp);return InteractionResult.CONSUME;}if(SbwCompat.isMonitor(held)){Ndc01Monitor.clear(held);return super.interact(p,hand);}}return level().isClientSide?InteractionResult.SUCCESS:super.interact(p,hand);}
 public boolean pack(ServerPlayer p){if(PlatformInventory.guard(this,p))return false;if(!canUse(p)||busy()||!getPassengers().isEmpty()||getDeltaMovement().lengthSqr()>.0004)return fail(p,6);if(operator()!=null)VatagSessions.stop(operator());var item=com.atsuishio.superbwarfare.item.container.ContainerBlockItem.createInstance(this);if(!p.getInventory().add(item)&&p.drop(item,false)==null)return false;settled=true;bays.clearContent();discard();return true;}
 private void dropCargo(){PlatformInventory.closeFor(this);if(settled)return;settled=true;for(int i=0;i<18;i++){var s=bays.removeItemNoUpdate(i);if(!s.isEmpty())super.spawnAtLocation(s.copy(),0);}syncCargo();}
 @Override public void destroy(){if(level().isClientSide)return;dropCargo();super.destroy();}
 @Override public net.minecraft.world.entity.item.ItemEntity spawnAtLocation(ItemStack s,float offset){return suppressDrops?null:super.spawnAtLocation(s,offset);}
 @Override public void remove(RemovalReason why){if(isRemoved())return;if(!level().isClientSide){PlatformInventory.closeFor(this);if(why.shouldDestroy()){dropCargo();DefenseData.get((ServerLevel)level()).remove((ServerLevel)level(),getUUID());}if(operator()!=null)VatagSessions.stop(operator());if(level()instanceof ServerLevel l)for(var p:l.getServer().getPlayerList().getPlayers())if(p.containerMenu instanceof Ndc01Menu m&&m.carrierId==getId())p.closeContainer();ChunkTicketManager.releaseDrone(this);}suppressDrops=true;try{super.remove(why);}finally{suppressDrops=false;}}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);var items=NonNullList.withSize(18,ItemStack.EMPTY);for(int i=0;i<18;i++)items.set(i,bays.getItem(i));ContainerHelper.saveAllItems(n,items);var ids=new ListTag();for(int i=0;i<18;i++){var t=new CompoundTag();t.putInt("Slot",i);if(loadIds[i]!=null)t.putUUID("Load",loadIds[i]);ids.add(t);}n.put("NdcLoads",ids);if(navalOwner!=null)n.putUUID("NdcOwner",navalOwner);n.putString("NdcOwnerName",ownerName);if(selectedTarget!=null)n.putUUID("NdcTarget",selectedTarget);n.putBoolean("NdcSettled",settled);n.putLong("NdcNext",nextLaunch);n.putBoolean("NdcDeparting",phase()==3);n.putInt("NdcBay",bay());n.putLong("NdcStart",entityData.get(START));}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);navalOwner=n.hasUUID("NdcOwner")?n.getUUID("NdcOwner"):null;ownerName=n.getString("NdcOwnerName");settled=n.getBoolean("NdcSettled");var items=NonNullList.withSize(18,ItemStack.EMPTY);ContainerHelper.loadAllItems(n,items);for(int i=0;i<18;i++)bays.setItem(i,items.get(i));for(var v:n.getList("NdcLoads",10)){var t=(CompoundTag)v;int i=t.getInt("Slot");if(i>=0&&i<18&&t.hasUUID("Load")&&!bays.getItem(i).isEmpty())loadIds[i]=t.getUUID("Load");}selectedTarget=n.hasUUID("NdcTarget")?n.getUUID("NdcTarget"):null;nextLaunch=Math.max(level().getGameTime(),n.getLong("NdcNext"));entityData.set(PHASE,0);entityData.set(BAY,-1);int savedBay=n.getInt("NdcBay");if(n.getBoolean("NdcDeparting")&&savedBay>=0&&savedBay<18&&bays.getItem(savedBay).isEmpty()){entityData.set(BAY,savedBay);entityData.set(PHASE,3);entityData.set(START,Math.min(level().getGameTime(),n.getLong("NdcStart")));}pendingActor=pendingLoad=pendingTarget=pendingEntity=null;}
 @Override public double getTargetSpeed(){return super.getTargetSpeed()*Ndc01Config.SPEED.get();}
 @Override public int getMaxEnergy(){return Ndc01Config.ENERGY.get();}
 @Override public float getMaxHealth(){return VehicleProfiles.health(this,Ndc01Config.HEALTH.get().floatValue());}
 public UUID defenseId(){return getUUID();}public UUID defenseOwner(){return navalOwner;}public String defenseOwnerName(){return ownerName;}public ServerLevel defenseLevel(){return(ServerLevel)level();}public Vec3 defensePosition(){return position();}public Entity defenseEntity(){return this;}
 public boolean defenseAvailable(){if(busy()||getEnergy()<Ndc01Config.LAUNCH.get()||!floating()||!isAlive()||isWreck()||level().getGameTime()<nextLaunch)return false;for(int i=0;i<18;i++)if(cargo(i).getItem()==AddonItems.ID01.get())return true;return false;}
 public boolean defenseRequest(ServerPlayer p,UUID target,UUID radar){if(!Objects.equals(radar,radar())||!DefenseData.get((ServerLevel)level()).navalAllows((ServerLevel)level(),radar,getUUID(),p))return false;var owner=navalOwner==null?null:((ServerLevel)level()).getServer().getPlayerList().getPlayer(navalOwner);for(int i=0;i<18;i++)if(cargo(i).getItem()==AddonItems.ID01.get()&&request(p==null?null:owner,i,loadId(i),target,p==null))return true;return false;}
}
